import{_ as i,l as o,o as e,c as n,v as t,p as h,x as l,d as m,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"验证集与泛化缺口","description":"","frontmatter":{"title":"验证集与泛化缺口","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/val-gen-gap.md","filePath":"llm/val-gen-gap.md","lastUpdated":1789023840000}'),p={name:"llm/val-gen-gap.md"};function E(A,a,_,c,B,f){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="验证集与泛化缺口" tabindex="-1">验证集与泛化缺口 <a class="header-anchor" href="#验证集与泛化缺口" aria-label="Permalink to &quot;验证集与泛化缺口&quot;">​</a></h1><div class="epigraph"><p>训练损失只说明模型记住了用来更新参数的那些样本；要谈「换一批会怎样」，必须有从未进入过梯度的数据。</p><footer>—— 据 Hastie, Tibshirani &amp; Friedman, The Elements of Statistical Learning；Goodfellow et al., Deep Learning, 2016 整理</footer></div><p><a href="/llm/momentum-adaptive-lr">动量与自适应学习率</a>让训练损失可以稳定下降。本课不重写 Adam。缺口是：下降的那条曲线用的样本，正是梯度来源。它变小，可能是学会了规律，也可能是记住了这批句子的编号。方法是划出验证集：不参与 \\(\\theta\\) 的更新，只定期前向。训练损失与验证损失之差，本课称为泛化缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>小批量 SGD 最小化的是经验风险 \\(\\hat R(\\theta)=\\frac{1}{N}\\sum_{i=1}^N\\ell(x_i,y_i;\\theta)\\)。我们真正关心的是同一分布上的期望风险 \\(R(\\theta)=\\mathbb{E}[\\ell]\\)。两者不必一起走。容量足够时，\\(\\hat R\\) 可以到接近 \\(0\\)，而 \\(R\\) 停在一个平台甚至回升。缺口不是再换一个优化器，而是承认经验风险不是目标本身，并给出一个可计算的代理。</p><p>验证集 \\(D_{\\mathrm{val}}\\) 从同一数据流程里留出，且与训练集不相交。在 \\(D_{\\mathrm{val}}\\) 上算平均损失或下游指标，得到 \\(R\\) 的粗糙估计。测试集再留一层，只在最终报告时用一次；反复用测试集调 \\(\\eta\\)、调早停，测试集就变成了第二验证集，缺口的估计会偏乐观。本课把「调参用验证、报告用测试」写成纪律，不把交叉验证的全部折法铺开。</p><h3 id="验证损失不是「没见过的训练损失」这么含糊" tabindex="-1">验证损失不是「没见过的训练损失」这么含糊 <a class="header-anchor" href="#验证损失不是「没见过的训练损失」这么含糊" aria-label="Permalink to &quot;验证损失不是「没见过的训练损失」这么含糊&quot;">​</a></h3><p>关键是<strong>从未进入过任何一次</strong> \\(g_{\\mathcal{B}}\\)。若某条样本曾经在某个 epoch 里更新过 \\(\\theta\\)，它就不是验证。从训练集里随机再抽一批来画「验证曲线」，测到的仍是经验风险的另一份平均，缺口会被缩小。数据泄漏的更隐蔽形式包括：按句打乱但同一篇文章的两句分属训练与验证、用验证文本做过子词词表、用验证指标选了检查点再在同一验证集上报数。本课要求划分发生在一切拟合之前。</p><p><span class="marginnote">语言模型里两条曲线常用同一交叉熵。单位必须一致：都是按 token 平均，还是按序列平均。填充、不同长度、不同领域混在验证里，都会让缺口的数值不可比。先固定计分协议，再谈差距。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>划分确定后，训练循环每隔固定步数：切到 eval 模式（关掉 dropout 等随机层），在 \\(D_{\\mathrm{val}}\\) 上前向，记录 \\(L_{\\mathrm{val}}\\)。不反向、不更新。比较 \\(L_{\\mathrm{train}}\\) 与 \\(L_{\\mathrm{val}}\\) 要用相近的滑窗，避免把瞬时小批量噪声当成缺口。\\(L_{\\mathrm{val}}\\) 持续下降：还在拟合规律。\\(L_{\\mathrm{train}}\\) 仍降、\\(L_{\\mathrm{val}}\\) 升：缺口在扩大，下一课的早停与权重衰减针对的就是这一段。</p><p>分布是否相同是假设。验证若来自另一领域，缺口混进了域移，不能只当过拟合读。本课默认独立同分布抽样；域移是数据课的缺口。</p>',12)),(e(),h(d,null,{default:l(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALL%5B%22%E5%85%A8%E9%83%A8%E8%AF%AD%E6%96%99%22%5D%20--%3E%20TR%5B%22%E8%AE%AD%E7%BB%83%E9%9B%86%E8%BF%9B%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20ALL%20--%3E%20VA%5B%22%E9%AA%8C%E8%AF%81%E9%9B%86%E5%8F%AA%E5%89%8D%E5%90%91%22%5D%0A%20%20ALL%20--%3E%20TE%5B%22%E6%B5%8B%E8%AF%95%E9%9B%86%E6%9C%80%E7%BB%88%E6%8A%A5%E5%91%8A%22%5D%0A%20%20TR%20--%3E%20LT%5B%22%E8%AE%AD%E7%BB%83%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20VA%20--%3E%20LV%5B%22%E9%AA%8C%E8%AF%81%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20LT%20--%3E%20GAP%5B%22%E6%B3%9B%E5%8C%96%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20LV%20--%3E%20GAP%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>参数更新在 \\(\\hat R\\) 的几何里走。验证曲线是在问：走的这条路径，在没见过的样本上是否同一方向。缺口扩大，说明路径在利用训练集的特异结构——编号共现、模板套话、标注伪影。优化器越强、容量越大，越容易走这条路，所以「训练更顺」不是成功标准。</p><p>选择检查点时应用 \\(L_{\\mathrm{val}}\\)（或验证集上的任务指标），不要用 \\(L_{\\mathrm{train}}\\)。这会引入对验证集的轻度过拟合：早停时刻本身是用验证信息选的。只要测试集仍封存，报告仍有意义。把验证、测试混用，机制就坏了。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给出泛化界，不把 VC 维请进来。下一课<a href="/llm/overfit-wd-earlystop">过拟合、权重衰减与早停</a>才谈如何把缺口压回去。后课默认：说到「模型变好」，指验证（或封存测试）上的指标；训练损失只是优化是否在工作的诊断。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>训练损失是经验风险；泛化要看从未进入梯度的验证损失。</li><li>验证与测试必须分开；用测试集调参会把报告变乐观。</li><li>划分要在拟合之前，避免篇章级泄漏与词表泄漏。</li><li>缺口扩大是下一课正则与早停的信号，不是再降 \\(\\eta\\) 就能解释。</li><li>出处：Hastie et al., ESL；Goodfellow et al., Deep Learning, 2016。</li></ul>',7))])}const L=i(p,[["render",E]]);export{D as __pageData,L as default};
